import React, { useState, useEffect } from 'react';
import { BarChart3, TrendingUp, TrendingDown, DollarSign, Users, Calendar } from 'lucide-react';
import { motion } from 'framer-motion';
import api from '../utils/api';
import '../styles/analytics.css';

export default function Analytics() {
  const [analytics, setAnalytics] = useState(null);
  const [loading, setLoading] = useState(true);
  const [timeRange, setTimeRange] = useState('month');

  const fetchAnalytics = async () => {
    try {
      const response = await api.get(`/analytics?range=${timeRange}`);
      setAnalytics(response.data);
    } catch (error) {
      console.error('Error fetching analytics:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAnalytics();
  }, [timeRange]);

  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Loading analytics...</p>
      </div>
    );
  }

  return (
    <div className="analytics-container">
      <div className="analytics-header">
        <div className="header-content">
          <h1>Analytics</h1>
          <p>Track your expenses and group insights</p>
        </div>
        <div className="time-range-selector">
          <select value={timeRange} onChange={(e) => setTimeRange(e.target.value)}>
            <option value="week">Last Week</option>
            <option value="month">Last Month</option>
            <option value="quarter">Last Quarter</option>
            <option value="year">Last Year</option>
          </select>
        </div>
      </div>

      <div className="stats-grid">
        <motion.div
          className="stat-card primary"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
        >
          <div className="stat-icon">
            <DollarSign size={24} />
          </div>
          <div className="stat-content">
            <h3>Total Spent</h3>
            <p className="stat-value">${analytics?.totalSpent || 0}</p>
            <div className="stat-change positive">
              <TrendingUp size={16} />
              <span>+12% from last period</span>
            </div>
          </div>
        </motion.div>

        <motion.div
          className="stat-card secondary"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
        >
          <div className="stat-icon">
            <Users size={24} />
          </div>
          <div className="stat-content">
            <h3>Active Groups</h3>
            <p className="stat-value">{analytics?.activeGroups || 0}</p>
            <div className="stat-change neutral">
              <span>No change</span>
            </div>
          </div>
        </motion.div>

        <motion.div
          className="stat-card tertiary"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
        >
          <div className="stat-icon">
            <Calendar size={24} />
          </div>
          <div className="stat-content">
            <h3>Transactions</h3>
            <p className="stat-value">{analytics?.totalTransactions || 0}</p>
            <div className="stat-change positive">
              <TrendingUp size={16} />
              <span>+8% from last period</span>
            </div>
          </div>
        </motion.div>

        <motion.div
          className="stat-card quaternary"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.4 }}
        >
          <div className="stat-icon">
            <BarChart3 size={24} />
          </div>
          <div className="stat-content">
            <h3>Avg. Transaction</h3>
            <p className="stat-value">${analytics?.avgTransaction || 0}</p>
            <div className="stat-change negative">
              <TrendingDown size={16} />
              <span>-3% from last period</span>
            </div>
          </div>
        </motion.div>
      </div>

      <div className="charts-grid">
        <motion.div
          className="chart-card"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.5 }}
        >
          <div className="chart-header">
            <h3>Spending Trend</h3>
            <div className="chart-legend">
              <div className="legend-item">
                <div className="legend-color primary"></div>
                <span>Your Spending</span>
              </div>
              <div className="legend-item">
                <div className="legend-color secondary"></div>
                <span>Group Average</span>
              </div>
            </div>
          </div>
          <div className="chart-placeholder">
            <BarChart3 size={48} />
            <p>Chart visualization would go here</p>
          </div>
        </motion.div>

        <motion.div
          className="chart-card"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.6 }}
        >
          <div className="chart-header">
            <h3>Category Breakdown</h3>
          </div>
          <div className="category-list">
            {analytics?.categories?.map((category, index) => (
              <div key={index} className="category-item">
                <div className="category-info">
                  <span className="category-name">{category.name}</span>
                  <span className="category-amount">${category.amount}</span>
                </div>
                <div className="category-bar">
                  <div
                    className="category-fill"
                    style={{ width: `${category.percentage}%` }}
                  ></div>
                </div>
              </div>
            )) || (
              <div className="no-data">
                <p>No category data available</p>
              </div>
            )}
          </div>
        </motion.div>
      </div>

      <motion.div
        className="recent-activity"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.7 }}
      >
        <h3>Recent Activity</h3>
        <div className="activity-list">
          {analytics?.recentActivity?.map((activity, index) => (
            <div key={index} className="activity-item">
              <div className="activity-icon">
                <DollarSign size={16} />
              </div>
              <div className="activity-details">
                <p className="activity-description">{activity.description}</p>
                <p className="activity-meta">{activity.group} - {activity.date}</p>
              </div>
              <div className="activity-amount">
                <span className={activity.type === 'expense' ? 'negative' : 'positive'}>
                  {activity.type === 'expense' ? '-' : '+'}${activity.amount}
                </span>
              </div>
            </div>
          )) || (
            <div className="no-data">
              <p>No recent activity</p>
            </div>
          )}
        </div>
      </motion.div>
    </div>
  );
}
